1	<!DOCTYPE html>
2	<html lang="en">
3	<head>
4	<meta charset="utf-8">
5	<meta name="viewport" content="width=device-width, initial-scale=1">
6	<title>Calculator</title>
7	<style>
8	  * { box-sizing: border-box; }
9	  body {
10	    margin: 0;
11	    min-height: 100vh;
12	    display: flex;
13	    align-items: center;
14	    justify-content: center;
15	    background: #e9ebef;
16	    font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
17	  }
18	  .calc {
19	    width: 320px;
20	    max-width: calc(100vw - 32px);
21	    padding: 16px;
22	    border-radius: 20px;
23	    background: #1f2229;
24	    box-shadow: 0 12px 32px rgba(0, 0, 0, 0.25);
25	  }
26	  .display {
27	    height: 88px;
28	    margin-bottom: 16px;
29	    padding: 0 12px;
30	    display: flex;
31	    align-items: flex-end;
32	    justify-content: flex-end;
33	    overflow: hidden;
34	    color: #fff;
35	    font-size: 48px;
36	    font-weight: 300;
37	    white-space: nowrap;
38	    font-variant-numeric: tabular-nums;
39	  }
40	  .keys {
41	    display: grid;
42	    grid-template-columns: repeat(4, 1fr);
43	    gap: 10px;
44	  }
45	  button {
46	    height: 64px;
47	    border: 0;
48	    border-radius: 14px;
49	    font: inherit;
50	    font-size: 24px;
51	    color: #fff;
52	    background: #3a3f4a;
53	    cursor: pointer;
54	  }
55	  button:hover { filter: brightness(1.12); }
56	  button:active { filter: brightness(0.9); }
57	  button:focus-visible { outline: 2px solid #8ab4ff; outline-offset: 2px; }
58	  .op { background: #f59e0b; }
59	  .op.active { background: #fff; color: #f59e0b; }
60	  .fn { background: #a5a9b3; color: #1f2229; }
61	  .wide { grid-column: span 2; }
62	</style>
63	</head>
64	<body>
65	<div class="calc">
66	  <div class="display" data-testid="calc-display" data-value="0" aria-live="polite">0</div>
67	  <div class="keys">
68	    <button class="fn wide" data-testid="key-clear" data-action="clear">AC</button>
69	    <button class="op" data-testid="key-div" data-op="/" aria-label="divide">÷</button>
70	    <button class="op" data-testid="key-mul" data-op="*" aria-label="multiply">×</button>
71	
72	    <button data-testid="key-7" data-digit="7">7</button>
73	    <button data-testid="key-8" data-digit="8">8</button>
74	    <button data-testid="key-9" data-digit="9">9</button>
75	    <button class="op" data-testid="key-sub" data-op="-" aria-label="subtract">−</button>
76	
77	    <button data-testid="key-4" data-digit="4">4</button>
78	    <button data-testid="key-5" data-digit="5">5</button>
79	    <button data-testid="key-6" data-digit="6">6</button>
80	    <button class="op" data-testid="key-add" data-op="+" aria-label="add">+</button>
81	
82	    <button data-testid="key-1" data-digit="1">1</button>
83	    <button data-testid="key-2" data-digit="2">2</button>
84	    <button data-testid="key-3" data-digit="3">3</button>
85	    <button class="op" data-testid="key-equals" data-action="equals" aria-label="equals">=</button>
86	
87	    <button class="wide" data-testid="key-0" data-digit="0">0</button>
88	    <button data-testid="key-dot" data-action="dot" aria-label="decimal point">.</button>
89	  </div>
90	</div>
91	<script>
92	(function () {
93	  var display = document.querySelector('[data-testid="calc-display"]');
94	  var opButtons = document.querySelectorAll('[data-op]');
95	
96	  // entry: string being typed, or null when showing a stored value.
97	  // value: number currently shown when entry is null.
98	  var state;
99	
100	  function reset() {
101	    state = { entry: null, value: 0, stored: null, op: null, error: false };
102	  }
103	
104	  function compute(a, op, b) {
105	    switch (op) {
106	      case '+': return a + b;
107	      case '-': return a - b;
108	      case '*': return a * b;
109	      case '/': return a / b;
110	    }
111	    return b;
112	  }
113	
114	  function currentNumber() {
115	    return state.entry !== null ? parseFloat(state.entry) : state.value;
116	  }
117	
118	  function formatValue(n) {
119	    var s = String(n);
120	    if (s.length <= 12) return s;
121	    // Trim floating-point noise and very long numbers for the visible text only.
122	    var trimmed = String(parseFloat(n.toPrecision(12)));
123	    if (trimmed.length <= 14) return trimmed;
124	    return n.toExponential(6).replace(/\.?0+e/, 'e');
125	  }
126	
127	  function render() {
128	    var text;
129	    if (state.error) {
130	      text = 'Error';
131	    } else if (state.entry !== null) {
132	      text = state.entry;
133	    } else {
134	      text = formatValue(state.value);
135	    }
136	    display.textContent = text;
137	    display.setAttribute('data-value', state.error ? 'NaN' : String(currentNumber()));
138	
139	    var len = text.length;
140	    display.style.fontSize = len > 12 ? '28px' : len > 9 ? '36px' : '48px';
141	
142	    for (var i = 0; i < opButtons.length; i++) {
143	      var b = opButtons[i];
144	      b.classList.toggle('active', state.entry === null && state.op === b.getAttribute('data-op'));
145	    }
146	  }
147	
148	  function inputDigit(d) {
149	    if (state.error) reset();
150	    if (state.entry === null || state.entry === '0') {
151	      state.entry = d;
152	    } else {
153	      state.entry += d;
154	    }
155	  }
156	
157	  function inputDot() {
158	    if (state.error) reset();
159	    if (state.entry === null) {
160	      state.entry = '0.';
161	    } else if (state.entry.indexOf('.') === -1) {
162	      state.entry += '.';
163	    }
164	  }
165	
166	  function setResult(n) {
167	    if (!isFinite(n)) {
168	      reset();
169	      state.error = true;
170	      return;
171	    }
172	    state.value = n;
173	  }
174	
175	  function inputOp(op) {
176	    if (state.error) return;
177	    if (state.entry !== null) {
178	      var n = parseFloat(state.entry);
179	      state.entry = null;
180	      if (state.op !== null && state.stored !== null) {
181	        setResult(compute(state.stored, state.op, n));
182	        if (state.error) return;
183	      } else {
184	        state.value = n;
185	      }
186	    }
187	    state.stored = state.value;
188	    state.op = op;
189	  }
190	
191	  function equals() {
192	    if (state.error || state.op === null) {
193	      if (state.entry !== null) {
194	        state.value = parseFloat(state.entry);
195	        state.entry = null;
196	      }
197	      return;
198	    }
199	    var b = currentNumber();
200	    state.entry = null;
201	    var op = state.op;
202	    state.op = null;
203	    var a = state.stored;
204	    state.stored = null;
205	    setResult(compute(a, op, b));
206	  }
207	
208	  document.querySelector('.keys').addEventListener('click', function (e) {
209	    var btn = e.target.closest('button');
210	    if (!btn) return;
211	    if (btn.hasAttribute('data-digit')) inputDigit(btn.getAttribute('data-digit'));
212	    else if (btn.hasAttribute('data-op')) inputOp(btn.getAttribute('data-op'));
213	    else {
214	      var action = btn.getAttribute('data-action');
215	      if (action === 'dot') inputDot();
216	      else if (action === 'equals') equals();
217	      else if (action === 'clear') reset();
218	    }
219	    render();
220	  });
221	
222	  document.addEventListener('keydown', function (e) {
223	    if (e.ctrlKey || e.metaKey || e.altKey) return;
224	    var k = e.key;
225	    if (/^[0-9]$/.test(k)) inputDigit(k);
226	    else if (k === '.' || k === ',') inputDot();
227	    else if (k === '+' || k === '-' || k === '*' || k === '/') inputOp(k);
228	    else if (k === 'Enter' || k === '=') equals();
229	    else if (k === 'Escape' || k === 'c' || k === 'C') reset();
230	    else return;
231	    e.preventDefault();
232	    render();
233	  });
234	
235	  reset();
236	  render();
237	})();
238	</script>
239	</body>
240	</html>
